        else {
            isEnumType = false;
            isInterface = false;
            // When the component type is primitive and is annotated with ElementType.TYPE_USE then
            // the typeMirror#toString returns (@CustomAnnotation :: byte) for the javac compiler
            if ( mirror.getKind().isPrimitive() ) {
